@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: inline-flex;
    flex-direction: column;
    min-width: 0;
    align-items: center;
    gap: var(--moduix-angle-slider-gap, var(--moduix-spacing-3));
    color: var(--moduix-angle-slider-color, var(--moduix-color-foreground));

    &[data-disabled] {
      opacity: var(--moduix-angle-slider-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .label {
    color: var(
      --moduix-angle-slider-label-color,
      var(--moduix-angle-slider-color, var(--moduix-color-foreground))
    );
    font-size: var(--moduix-angle-slider-label-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-angle-slider-label-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-angle-slider-label-line-height, var(--moduix-line-height-text-sm));
    text-align: center;
  }

  .control {
    --_angle-slider-fill-color: var(
      --moduix-angle-slider-indicator-bg,
      var(--moduix-color-primary)
    );
    --_angle-slider-track-color: var(--moduix-angle-slider-track-bg, var(--moduix-color-muted));
    --_angle-slider-thumb-border-color: var(
      --moduix-angle-slider-thumb-border-color,
      var(--moduix-color-border)
    );

    position: relative;
    box-sizing: border-box;
    width: var(--moduix-angle-slider-size, 8rem);
    min-width: 0;
    aspect-ratio: 1;
    border-radius: var(--moduix-radius-full);
    cursor: pointer;
    outline: 0;
    user-select: none;

    &::before {
      position: absolute;
      inset: 0;
      border-radius: inherit;
      background: conic-gradient(
        from 0deg,
        var(--_angle-slider-fill-color) var(--angle, 0deg),
        var(--_angle-slider-track-color) var(--angle, 0deg)
      );
      mask: radial-gradient(
        closest-side,
        transparent calc(100% - var(--moduix-angle-slider-ring-thickness, 0.5rem) - 1px),
        #000 calc(100% - var(--moduix-angle-slider-ring-thickness, 0.5rem))
      );
      content: '';
    }

    &::after {
      position: absolute;
      top: calc(var(--moduix-angle-slider-ring-thickness, 0.5rem) / 2);
      left: 50%;
      z-index: 1;
      width: var(--moduix-angle-slider-ring-thickness, 0.5rem);
      height: var(--moduix-angle-slider-ring-thickness, 0.5rem);
      border-radius: var(--moduix-radius-full);
      background: var(--_angle-slider-fill-color);
      transform: translate(-50%, -50%);
      content: '';
    }

    @media (hover: hover) {
      &:not([data-disabled], [data-readonly]):hover::before {
        --_angle-slider-track-color: var(
          --moduix-angle-slider-track-bg-hover,
          var(--moduix-angle-slider-track-bg, var(--moduix-color-muted))
        );
      }
    }

    &:not([data-disabled], [data-readonly]):active::before {
      --_angle-slider-track-color: var(
        --moduix-angle-slider-track-bg-active,
        var(--moduix-angle-slider-track-bg, var(--moduix-color-muted))
      );
    }

    &:active:not([data-disabled], [data-readonly]) .thumb::before {
      border-color: var(--moduix-angle-slider-focus-ring-color, var(--moduix-color-ring));
      box-shadow:
        0 0 0 var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
          var(--moduix-angle-slider-focus-ring-color, var(--moduix-color-ring)),
        var(--moduix-angle-slider-thumb-shadow-dragging, var(--moduix-shadow-md));
    }

    &[data-invalid] {
      --_angle-slider-fill-color: var(
        --moduix-angle-slider-invalid-indicator-bg,
        var(--moduix-angle-slider-invalid-color, var(--moduix-color-destructive))
      );
      --_angle-slider-thumb-border-color: var(
        --moduix-angle-slider-invalid-indicator-bg,
        var(--moduix-angle-slider-invalid-color, var(--moduix-color-destructive))
      );
    }

    &:is([data-disabled], [data-readonly]) {
      cursor: default;
    }
  }

  .thumb {
    position: absolute;
    top: 0;
    bottom: 0;
    left: 50%;
    z-index: 2;
    width: 0;
    outline: 0;

    &::before {
      position: absolute;
      top: calc(var(--moduix-angle-slider-ring-thickness, 0.5rem) / 2);
      left: 0;
      box-sizing: border-box;
      width: var(--moduix-angle-slider-thumb-size, var(--moduix-spacing-4));
      height: var(--moduix-angle-slider-thumb-size, var(--moduix-spacing-4));
      border: var(--moduix-angle-slider-thumb-border-width, var(--moduix-border-width-sm)) solid
        var(--_angle-slider-thumb-border-color);
      border-radius: var(--moduix-angle-slider-thumb-radius, var(--moduix-radius-full));
      background: var(--moduix-angle-slider-thumb-bg, var(--moduix-color-background));
      box-shadow: var(--moduix-angle-slider-thumb-shadow, var(--moduix-shadow-sm));
      transform: translate(-50%, -50%);
      transition:
        border-color var(--moduix-angle-slider-transition, var(--moduix-transition-default)),
        background-color var(--moduix-angle-slider-transition, var(--moduix-transition-default)),
        box-shadow var(--moduix-angle-slider-transition, var(--moduix-transition-default));
      content: '';
    }

    &:focus-visible::before {
      border-color: var(--moduix-angle-slider-focus-ring-color, var(--moduix-color-ring));
      box-shadow: 0 0 0 var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        var(--moduix-angle-slider-focus-ring-color, var(--moduix-color-ring));
    }

    &[data-disabled] {
      pointer-events: none;
    }
  }

  .markerGroup {
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
  }

  .marker {
    position: absolute;
    inset: 0;

    &::before {
      position: absolute;
      top: calc(var(--moduix-angle-slider-ring-thickness, 0.5rem) / 2);
      left: 50%;
      width: var(--moduix-angle-slider-marker-width, 0.125rem);
      height: var(--moduix-angle-slider-marker-height, 0.5rem);
      border-radius: var(--moduix-radius-full);
      background: var(--moduix-angle-slider-marker-color, var(--moduix-color-muted-foreground));
      transform: translate(-50%, -50%);
      content: '';
    }

    &[data-state='under-value']::before {
      background: var(--moduix-angle-slider-marker-active-color, var(--moduix-color-primary));
    }

    &[data-state='at-value']::before {
      background: var(--moduix-angle-slider-marker-current-color, var(--moduix-color-foreground));
    }
  }

  .valueText {
    color: var(
      --moduix-angle-slider-value-text-color,
      var(--moduix-angle-slider-color, var(--moduix-color-foreground))
    );
    font-size: var(--moduix-angle-slider-value-text-font-size, var(--moduix-text-lg));
    font-weight: var(--moduix-angle-slider-value-text-font-weight, var(--moduix-weight-medium));
    font-variant-numeric: tabular-nums;
    line-height: var(
      --moduix-angle-slider-value-text-line-height,
      var(--moduix-line-height-text-lg)
    );
    text-align: center;
  }

  .control .valueText {
    position: absolute;
    inset: 0;
    z-index: 1;
    display: grid;
    place-items: center;
  }

  @media (prefers-reduced-motion: reduce) {
    .thumb::before {
      transition: none;
    }
  }
}

import {
  AngleSliderContext,
  AngleSliderHiddenInput,
  useAngleSlider,
  useAngleSliderContext,
} from '@ark-ui/vue/angle-slider';
import type {
  AngleSliderRootProps,
  UseAngleSliderProps,
  UseAngleSliderReturn,
} from '@ark-ui/vue/angle-slider';
import AngleSlider from './AngleSlider.vue';
import AngleSliderControl from './AngleSliderControl.vue';
import AngleSliderDial from './AngleSliderDial.vue';
import AngleSliderLabel from './AngleSliderLabel.vue';
import AngleSliderMarker from './AngleSliderMarker.vue';
import AngleSliderMarkerGroup from './AngleSliderMarkerGroup.vue';
import AngleSliderMarks from './AngleSliderMarks.vue';
import AngleSliderRootProvider from './AngleSliderRootProvider.vue';
import AngleSliderThumb from './AngleSliderThumb.vue';
import AngleSliderValueText from './AngleSliderValueText.vue';

export {
  AngleSlider,
  AngleSliderContext,
  AngleSliderControl,
  AngleSliderDial,
  AngleSliderHiddenInput,
  AngleSliderLabel,
  AngleSliderMarker,
  AngleSliderMarkerGroup,
  AngleSliderMarks,
  AngleSliderRootProvider,
  AngleSliderThumb,
  AngleSliderValueText,
  useAngleSlider,
  useAngleSliderContext,
};

export type { AngleSliderRootProps, UseAngleSliderProps, UseAngleSliderReturn };
